class RowAction(str, Enum):
    """
    What should the pipeline do with this POS row? When several options fit, take the first
    that applies in this order: compliance_review, no_op, ask_human, duplicate,
    pack_qty_issue, vendor_rename, normalize, commit. (choice)
    """

    COMMIT = 'commit'
    """
    Clean row that matches master data - customer identical to the master name, canonical
    formats, quantity a whole multiple of SPQ and at least MOQ, ref not yet seen.
    """
    NORMALIZE = 'normalize'
    """
    Values are right but formatted differently - date style, thousands or decimal-comma
    separators, units or stray spaces, part number case or spacing, or a customer name
    differing only in case, punctuation or accents.
    """
    VENDOR_RENAME = 'vendor_rename'
    """
    Reported customer name differs from the master name beyond formatting but refers to the
    same entity - abbreviation, changed legal suffix, typo, rebrand, parent or subsidiary.
    """
    PACK_QTY_ISSUE = 'pack_qty_issue'
    """
    Quantity, once its format is normalized, is not a whole multiple of the part's SPQ or is
    below its MOQ.
    """
    COMPLIANCE_REVIEW = 'compliance_review'
    """Master data marks the row restricted=yes. Always wins over every other option."""
    DUPLICATE = 'duplicate'
    """
    The row's ref already appears in master seen_refs, ignoring letter case and extra
    spaces.
    """
    NO_OP = 'no_op'
    """
    Not a sales line - a repeated header, a subtotal or grand-total line, a blank or
    separator line, or a note. Skip it.
    """
    ASK_HUMAN = 'ask_human'
    """
    Looks like a sales line but cannot be trusted - a field missing, impossible or
    contradictory (zero or negative quantity, month 13), master lookup failed (unknown
    customer, spq or moq '?'), or nothing else fits.
    """


class NeedsHuman(str, Enum):
    """Must a person review this row before it is committed? (noul)"""

    YES = 'yes'
    """
    A person must review it - pack-quantity break, compliance flag, untrustworthy row, or a
    customer link that is only loosely supported.
    """
    NO = 'no'
    """
    The pipeline can handle it alone - clean row, format fix, clear rename, duplicate to
    drop, or non-sales line to skip.
    """


class Severity(str, Enum):
    """How much would committing this row unchanged distort the POS report? (score)"""

    V_0 = '0'
    """No effect - the row is right as reported."""
    V_1 = '1'
    """Cosmetic only - formatting, or a header, blank or note line with no quantity."""
    V_2 = '2'
    """Minor number drift for one line - a pack-quantity break or a clear customer rename."""
    V_3 = '3'
    """
    Wrong totals for one customer or part - a duplicate, a subtotal line, an uncertain
    customer link, or an untrustworthy line.
    """
    V_4 = '4'
    """
    Wrong totals across the report, or a compliance exposure - a grand-total line or a
    restricted party.
    """


